-- Disposable local database only. No real credentials, providers or production data.
CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE ROLE service_role NOLOGIN;
CREATE SCHEMA auth;
CREATE SCHEMA net;
CREATE TABLE unidades(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nome text);
CREATE TABLE user_roles(user_id uuid,role text);
CREATE TABLE user_unidades(user_id uuid,unidade_id uuid);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('test.uid',true),'')::uuid $$;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('test.role',true),'') $$;
CREATE FUNCTION has_role(uuid,text) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=$1 AND role=$2) $$;
CREATE FUNCTION get_user_unidades(uuid) RETURNS SETOF uuid LANGUAGE sql STABLE AS $$ SELECT unidade_id FROM user_unidades WHERE user_id=$1 $$;
CREATE TABLE leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nome text DEFAULT 'FIXTURE',unidade_id uuid REFERENCES unidades,ativo boolean DEFAULT true,is_matriculado boolean DEFAULT false,status_funil text DEFAULT 'aula_agendada',origem text,hora_aula_experimental time,data_aula_experimental timestamptz,updated_at timestamptz DEFAULT now());
CREATE TABLE interacoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lead_id uuid NOT NULL REFERENCES leads ON DELETE CASCADE,unidade_id uuid REFERENCES unidades,tipo text NOT NULL DEFAULT 'Agendamento Experimental',created_at timestamptz DEFAULT now(),created_by uuid,data_interacao timestamptz DEFAULT now(),descricao text,cadastrado_por text,atendido_por text,agendou_experimental boolean DEFAULT false,data_experimental date,hora_experimental time,compareceu boolean DEFAULT false,compareceu_em timestamptz,fechou_matricula boolean DEFAULT false,data_fechamento date,cancelado boolean DEFAULT false,cancelado_em timestamptz,motivo_cancelamento text,reagendou boolean DEFAULT false,confirmado boolean DEFAULT false,status_avaliacao text,contato_meta jsonb,treinador_experimental text);
CREATE TABLE follow_ups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lead_id uuid,unidade_id uuid,tipo text,data_referencia timestamptz,data_prevista timestamptz,status text DEFAULT 'pendente',cancelado_motivo text,concluido_em timestamptz,concluido_por text,updated_at timestamptz DEFAULT now(),UNIQUE(lead_id,tipo));
CREATE TABLE tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),titulo text,descricao text,responsavel text,setor text,prioridade text,prazo date,unidade_id uuid,status text DEFAULT 'pendente',notificado_24h boolean,notificado_prazo boolean,fu_gerencial_lead_id uuid,fu_gerencial_matricula_id uuid,fu_gerencial_etapa text,fu_gerencial_status text,fu_gerencial_envio_erro text,fu_tecnico_lead_id uuid,fu_tecnico_matricula_id uuid,fu_tecnico_etapa text,fu_tecnico_status text,fu_tecnico_envio_erro text,fu_matriculados_lead_id uuid,fu_matriculados_matricula_id uuid,fu_matriculados_confirmado_em timestamptz,fu_matriculados_envio_erro text);
CREATE UNIQUE INDEX tasks_fu_tecnico_ciclo ON tasks(fu_tecnico_lead_id,fu_tecnico_matricula_id,fu_tecnico_etapa) WHERE fu_tecnico_etapa IS NOT NULL;
CREATE UNIQUE INDEX tasks_fu_gerencial_ciclo ON tasks(fu_gerencial_lead_id,fu_gerencial_matricula_id,fu_gerencial_etapa) WHERE fu_gerencial_etapa IS NOT NULL;
CREATE UNIQUE INDEX tasks_fu_matriculados_ciclo ON tasks(fu_matriculados_matricula_id) WHERE fu_matriculados_matricula_id IS NOT NULL;
CREATE TABLE experimental_presenca_telegram(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),interacao_id uuid REFERENCES interacoes ON DELETE CASCADE,lead_id uuid,unidade_id uuid,data_aula date,hora_aula text,status text DEFAULT 'enviado',resultado text,origem_resposta text,respondido_por text,respondido_em timestamptz,telegram_chat_id bigint,telegram_message_id bigint,updated_at timestamptz DEFAULT now(),UNIQUE(interacao_id,data_aula,hora_aula));
ALTER TABLE experimental_presenca_telegram DROP CONSTRAINT experimental_presenca_telegra_interacao_id_data_aula_hora_a_key;
CREATE UNIQUE INDEX ux_exp_presenca_slot ON experimental_presenca_telegram(interacao_id,data_aula,hora_aula);
CREATE TABLE telegram_groups(id uuid DEFAULT gen_random_uuid(),unidade_id uuid,telegram_chat_id bigint,status text,group_type text);
CREATE TABLE cronograma_funcionarios(id uuid DEFAULT gen_random_uuid(),unidade_id uuid,user_id uuid,setor text,cargo text,ativo boolean DEFAULT true);
CREATE TABLE ops_notificacoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),usuario_id uuid,tipo text,titulo text,mensagem text,lida boolean DEFAULT false,created_at timestamptz DEFAULT now());
CREATE TABLE fixture_http(id bigint GENERATED ALWAYS AS IDENTITY,url text,body jsonb);
CREATE FUNCTION net.http_post(url text,body jsonb DEFAULT '{}',params jsonb DEFAULT '{}',headers jsonb DEFAULT '{}',timeout_milliseconds integer DEFAULT 1000) RETURNS bigint LANGUAGE plpgsql AS $$ DECLARE i bigint; BEGIN INSERT INTO fixture_http(url,body) VALUES(url,body) RETURNING id INTO i; RETURN i; END $$;
CREATE FUNCTION get_cron_secret() RETURNS text LANGUAGE sql AS $$ SELECT 'fixture-only' $$;
CREATE FUNCTION fu_gerencial_inicio() RETURNS timestamptz LANGUAGE sql AS $$ SELECT '2026-11-02T10:55:15Z'::timestamptz $$;
CREATE FUNCTION fu_matriculados_inicio() RETURNS timestamptz LANGUAGE sql AS $$ SELECT '2026-11-02T11:18:39Z'::timestamptz $$;
CREATE FUNCTION fu_next_weekday(date) RETURNS date LANGUAGE sql AS $$ SELECT $1+CASE extract(isodow FROM $1) WHEN 6 THEN 2 WHEN 7 THEN 1 ELSE 0 END $$;
CREATE FUNCTION contato_registrar_evidencia(uuid,uuid,text,text,text,uuid,text,text,text,text,timestamptz,text,integer,text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN RETURN; END $$;
GRANT USAGE ON SCHEMA public,auth TO authenticated,service_role;
GRANT SELECT ON unidades,leads,interacoes,experimental_presenca_telegram TO authenticated;
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;